use vstd::prelude::*;

verus! {

pub fn check_if_last_char_is_a_letter(txt: &str) -> bool
    // No special preconditions needed: works for any &str
    ensures
        // Result is true iff:
        //  - txt is non-empty
        //  - the last char is an ASCII alphabetic letter
        //  - and either txt has exactly one char, or the char before the last is a space
        result == ({
            let s = txt@;
            s.len() > 0
            && s[s.len() - 1].is_ascii_alphabetic()
            && (s.len() == 1 || s[s.len() - 2] == ' ')
        }),
{
    let mut chars = txt.chars();

    let last = match chars.next_back() {
        Some(c) => c,
        None => return false, // empty
    };

    if !last.is_ascii_alphabetic() {
        return false;
    }

    match chars.next_back() {
        None => true,             // exactly one character
        Some(prev) => prev == ' ', // preceding character must be a space
    }
}

} // verus!